import{_ as i,a0 as s,w as p,s as d,ao as l,I as t,x as r,a1 as a,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Linux free 命令 - 显示系统中空闲和已使用的内存 | LCTT x X-CMD","titleTemplate":false,"description":"Linux free 命令 - 显示系统中空闲和已使用的内存 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux free 命令 - 显示系统中空闲和已使用的内存 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux free 命令 - 显示系统中空闲和已使用的内存 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Linux free Command - Display Free and used Memory in the System","title":"Linux free 命令 - 显示系统中空闲和已使用的内存","tag":"201401","desc":""},"relativePath":"201401/Linux free Command - Display Free and used Memory in the System.md","filePath":"[post].md"}'),f={name:"201401/Linux free Command - Display Free and used Memory in the System.md"};function m(u,e,g,h,x,b){const n=s("Link");return p(),d("div",null,[e[21]||(e[21]=l(`<h1 id="linux-free-命令-显示系统中空闲和已使用的内存" tabindex="-1">Linux free 命令 - 显示系统中空闲和已使用的内存 <a class="header-anchor" href="#linux-free-命令-显示系统中空闲和已使用的内存" aria-label="Permalink to “Linux free 命令 - 显示系统中空闲和已使用的内存”">​</a></h1><p>系统管理员必须维护他们服务器的健康运行。其中一个重要的部分就是内存。当服务器内存使用率过高时，它会降低服务器的性能。Linux有一个称为 <strong>free</strong> 的工具，来监控内存使用率。</p><h3 id="free-命令是什么" tabindex="-1">free 命令是什么 <a class="header-anchor" href="#free-命令是什么" aria-label="Permalink to “free 命令是什么”">​</a></h3><p><strong>free</strong> 命令是一个显示系统中空闲和已用内存大小的工具。free 命令的输出和 top 命令相似。大多数Linux发行版已经含有 free 命令。</p><h3 id="如何运行-free" tabindex="-1">如何运行 free <a class="header-anchor" href="#如何运行-free" aria-label="Permalink to “如何运行 free”">​</a></h3><p>想要运行，只需在控制台输入<strong>free</strong> 即可。不带选项运行会显示一个以KB为单位的默认输出。</p><pre><code>$ free
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_default.png" alt="free默认视图"></p><p>从上面的截图我们看到：</p><h4 id="内存-以kb计" tabindex="-1">内存 (以KB计) <a class="header-anchor" href="#内存-以kb计" aria-label="Permalink to “内存 (以KB计)”">​</a></h4><ul><li>Total（全部） : 1026740</li><li>Used（已用） : 843396</li><li>Free（可用） : 183344</li><li>Shared（共享） : 0</li><li>Buffers（块设备缓存区） : 52704</li><li>Cached（文件缓存） : 376384</li></ul>`,11)),t("p",null,[e[1]||(e[1]=r("译注：关于Buffers和Cached的区别，来自 ",-1)),a(n,{href:"http://www.taobaotesting.com/blogs/qa?bid=2265"},{default:o(()=>[...e[0]||(e[0]=[r("http://www.taobaotesting.com/blogs/qa?bid=2265",-1)])]),_:1}),e[2]||(e[2]=r(" 的一段解释如下：",-1))]),e[22]||(e[22]=l(`<blockquote><p>buffers是指用来给块设备做的缓冲大小，他只记录文件系统的metadata以及 tracking in-flight pages.</p></blockquote><blockquote><p>cached是用来给文件做缓冲。</p></blockquote><blockquote><p>那就是说：buffers是用来存储，目录里面有什么内容，权限等等。而cached直接用来记忆我们打开的文件</p></blockquote><h4 id="swap-以kb计" tabindex="-1">Swap (以KB计) <a class="header-anchor" href="#swap-以kb计" aria-label="Permalink to “Swap (以KB计)”">​</a></h4><ul><li>Total（全部） : 1045500</li><li>Used（已用） : 3376</li><li>Free（可用） : 1042124</li></ul><p>当你看见 buffer/cache 的空闲空间低或者 swap 的空闲空间低，说明内存需要升级了。这意味这内存利用率很高。请注意 <strong>shared（共享）内存列应该被忽略</strong> ，因为它已经被废弃了。</p><h3 id="以其它单元显示内存信息" tabindex="-1">以其它单元显示内存信息 <a class="header-anchor" href="#以其它单元显示内存信息" aria-label="Permalink to “以其它单元显示内存信息”">​</a></h3><p>如我们先前提到的，默认 free 会以 KB 为单位显示信息。free 同样提供给我们 <strong>b (B), -k (KB), -m (MB), -g (GB) and –tera (TB)</strong>这些单位。要显示我们想要的单位，只要选择一个并在 free 后面跟上。下面一个是以 MB 为单位的输出样例。</p><pre><code>$ free -m
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_m.png" alt="free命令以MB为单位"></p><p>这个技巧同样适用于<strong>-b, -k, -g</strong> 以及 <strong>–tera</strong> 选项。</p><h3 id="以适于人类可读方式显示内存信息" tabindex="-1">以适于人类可读方式显示内存信息 <a class="header-anchor" href="#以适于人类可读方式显示内存信息" aria-label="Permalink to “以适于人类可读方式显示内存信息”">​</a></h3><p>free 同样提供了<strong>-h</strong>选项，这意味着适于人类可读(译注:系统上可能并不存在-h选项，已被-m取代)。那么这与其它的选项有什么不同呢，如<strong>-m</strong>(MB)选项？ 可见的最大不同是<strong>-h</strong>选项会在数字后面加上适于人类可读的单位。让我们看一个例子。</p><pre><code>$ free -h
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_h.png" alt="人类可读的free"></p><p>如我们一起看到的，在1,0数字后这里是<strong>G(GB)</strong>字母。当数字并没有达到GB时，free足够聪明来知道并在每个数字后面跟上合适的单位。后面的<strong>M</strong> - 数字929告诉我们它有929MB(译注: 原文为929 number tell us its 969 Megabytes，这里应该为输入错误)。</p><h3 id="间隔显示-free" tabindex="-1">间隔显示 free <a class="header-anchor" href="#间隔显示-free" aria-label="Permalink to “间隔显示 free”">​</a></h3><p>作为一个状态检查工具，最好的统计内存利用率的方法是使用延迟间隔。这么做的话，我们可以使用<strong>-s</strong>选项后面跟上我们想要间隔的N秒数。我们可以在后面合并几个选项来使输出满足我们的需求。假如我们想要每3秒统计一次内存利用率并且适于人类可读，那么就像这样做:</p><pre><code>$ free -hs 3
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_hs3.png" alt="间隔3s显示free"></p><h3 id="显示高低内存利用率" tabindex="-1">显示高低内存利用率 <a class="header-anchor" href="#显示高低内存利用率" aria-label="Permalink to “显示高低内存利用率”">​</a></h3><p>如果我们想要知道高低内存统计，我们可以使用-l选项。下面是一个例子。</p><pre><code>$ free -l
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_l.png" alt="Free 的 低-高 统计"></p><h3 id="显示-linux-全部内存" tabindex="-1">显示 Linux 全部内存 <a class="header-anchor" href="#显示-linux-全部内存" aria-label="Permalink to “显示 Linux 全部内存”">​</a></h3><p>如果我们需要每列的总计信息，我们可以在 free 命令后面跟上 <strong>-t</strong> 选项。这会在字底部额外加入一行显示。</p><pre><code>$ free -t
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/free_t.png" alt="free命令带总计内存"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3>`,29)),t("p",null,[e[4]||(e[4]=r("除了",-1)),a(n,{href:"http://linoxide.com/linux-command/linux-vmstat-command-tool-report-virtual-memory-statistics/"},{default:o(()=>[...e[3]||(e[3]=[r("vmstat",-1)])]),_:1}),e[5]||(e[5]=r("以外，free 命令也是一个用于统计内存利用率的简单统计工具。用这个你可以快速查看你的 Linux 内存信息。free 命令使用 ",-1)),e[6]||(e[6]=t("strong",null,"/proc/meminfo",-1)),e[7]||(e[7]=r(" 作为基准来显示内存利用率信息。如往常一样，你可以在控制台下输入 ",-1)),e[8]||(e[8]=t("strong",null,"man free",-1)),e[9]||(e[9]=r(" 来获取更多关于 free 的信息。",-1))]),e[23]||(e[23]=t("hr",null,null,-1)),t("p",null,[e[11]||(e[11]=r("via: ",-1)),a(n,{href:"http://linoxide.com/linux-command/linux-free-command/"},{default:o(()=>[...e[10]||(e[10]=[r("http://linoxide.com/linux-command/linux-free-command/",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=r("译者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:o(()=>[...e[12]||(e[12]=[r("geekpi",-1)])]),_:1}),e[15]||(e[15]=r(" 校对：",-1)),a(n,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...e[13]||(e[13]=[r("Caroline",-1)])]),_:1})]),t("p",null,[e[18]||(e[18]=r("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[16]||(e[16]=[r("LCTT",-1)])]),_:1}),e[19]||(e[19]=r(" 原创翻译，",-1)),a(n,{href:"http://linux.cn/"},{default:o(()=>[...e[17]||(e[17]=[r("Linux中国",-1)])]),_:1}),e[20]||(e[20]=r(" 荣誉推出",-1))])])}const C=i(f,[["render",m]]);export{L as __pageData,C as default};
